CREATE TYPE public.app_role AS ENUM ('admin');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own roles" ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM public,anon;
GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated;
CREATE FUNCTION public.touch_updated_at() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.updated_at=now(); RETURN NEW; END $$;
CREATE TABLE public.merchants (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid UNIQUE, name text NOT NULL, area text NOT NULL DEFAULT '', phone text NOT NULL DEFAULT '', category text NOT NULL DEFAULT '', business_type text NOT NULL DEFAULT '', active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.merchants TO authenticated;
GRANT ALL ON public.merchants TO service_role;
ALTER TABLE public.merchants ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Merchant own records" ON public.merchants FOR ALL TO authenticated USING(owner_id=auth.uid()) WITH CHECK(owner_id=auth.uid());
CREATE POLICY "Admin merchants" ON public.merchants FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TRIGGER merchants_touch BEFORE UPDATE ON public.merchants FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();
CREATE TABLE public.products (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),merchant_id uuid REFERENCES public.merchants(id),name text NOT NULL,category text NOT NULL DEFAULT '',price_kes integer NOT NULL DEFAULT 0 CHECK(price_kes>=0),stock integer NOT NULL DEFAULT 0 CHECK(stock>=0),active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.products TO authenticated;
GRANT ALL ON public.products TO service_role;
ALTER TABLE public.products ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Merchant products" ON public.products FOR ALL TO authenticated USING(EXISTS(SELECT 1 FROM public.merchants m WHERE m.id=merchant_id AND m.owner_id=auth.uid())) WITH CHECK(EXISTS(SELECT 1 FROM public.merchants m WHERE m.id=merchant_id AND m.owner_id=auth.uid()));
CREATE POLICY "Admin products" ON public.products FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TRIGGER products_touch BEFORE UPDATE ON public.products FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();
CREATE TABLE public.orders (id text PRIMARY KEY,merchant_id uuid REFERENCES public.merchants(id),customer_id uuid,merchant_name text NOT NULL,pickup_area text NOT NULL DEFAULT '',customer_area text NOT NULL DEFAULT '',customer_name text NOT NULL DEFAULT '',customer_phone text NOT NULL DEFAULT '',items_summary text NOT NULL DEFAULT '',total_kes integer NOT NULL DEFAULT 0 CHECK(total_kes>=0),status text NOT NULL DEFAULT 'Preparing',payment_status text NOT NULL DEFAULT 'Pending' CHECK(payment_status IN ('Pending','Paid','Failed','Refunded')),payment_method text NOT NULL DEFAULT '',delivery_fee_kes integer NOT NULL DEFAULT 0,service_fee_kes integer NOT NULL DEFAULT 0,rider_id uuid,pickup_lat double precision NOT NULL DEFAULT 0,pickup_lng double precision NOT NULL DEFAULT 0,drop_lat double precision NOT NULL DEFAULT 0,drop_lng double precision NOT NULL DEFAULT 0,rider_lat double precision,rider_lng double precision,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.orders TO authenticated;
GRANT ALL ON public.orders TO service_role;
ALTER TABLE public.orders ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Merchant orders" ON public.orders FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.merchants m WHERE m.id=merchant_id AND m.owner_id=auth.uid()));
CREATE POLICY "Customer orders" ON public.orders FOR SELECT TO authenticated USING(customer_id=auth.uid());
CREATE POLICY "Admin orders" ON public.orders FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
GRANT UPDATE ON public.orders TO authenticated;
CREATE TRIGGER orders_touch BEFORE UPDATE ON public.orders FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();
CREATE INDEX orders_merchant_created ON public.orders(merchant_id,created_at);
CREATE TABLE public.order_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id text NOT NULL REFERENCES public.orders(id),product_id uuid REFERENCES public.products(id),product_name text NOT NULL,quantity integer NOT NULL CHECK(quantity>0),unit_price_kes integer NOT NULL CHECK(unit_price_kes>=0));
GRANT SELECT ON public.order_items TO authenticated;
GRANT ALL ON public.order_items TO service_role;
ALTER TABLE public.order_items ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Visible order items" ON public.order_items FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.orders o WHERE o.id=order_id));
CREATE FUNCTION public.merchant_prepare_order(_order_id text,_status text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
IF _status NOT IN ('Ready for Pickup','Cancelled') THEN RAISE EXCEPTION 'Invalid preparation status'; END IF;
UPDATE public.orders o SET status=_status WHERE o.id=_order_id AND o.status IN ('Pending','Preparing') AND EXISTS(SELECT 1 FROM public.merchants m WHERE m.id=o.merchant_id AND m.owner_id=auth.uid());
IF NOT FOUND THEN RAISE EXCEPTION 'Order not available for preparation'; END IF;
END $$;
REVOKE ALL ON FUNCTION public.merchant_prepare_order(text,text) FROM public,anon;
GRANT EXECUTE ON FUNCTION public.merchant_prepare_order(text,text) TO authenticated;
CREATE TABLE public.riders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),full_name text NOT NULL DEFAULT '',phone text NOT NULL DEFAULT '',online boolean NOT NULL DEFAULT false,lat double precision,lng double precision,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE ON public.riders TO authenticated;
GRANT ALL ON public.riders TO service_role;
ALTER TABLE public.riders ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Admin riders" ON public.riders FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.support_tickets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),ticket_no bigint GENERATED ALWAYS AS IDENTITY,subject text NOT NULL,customer_name text NOT NULL DEFAULT '',customer_phone text NOT NULL DEFAULT '',order_id text,priority text NOT NULL DEFAULT 'Medium',status text NOT NULL DEFAULT 'Open',notes text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.support_tickets TO authenticated;
GRANT ALL ON public.support_tickets TO service_role;
ALTER TABLE public.support_tickets ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Admin tickets" ON public.support_tickets FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.advance_rider(order_id text) RETURNS void LANGUAGE plpgsql SET search_path=public AS $$ BEGIN RAISE EXCEPTION 'Rider location must come from the rider device'; END $$;
REVOKE ALL ON FUNCTION public.advance_rider(text) FROM public,anon;
GRANT EXECUTE ON FUNCTION public.advance_rider(text) TO authenticated;
ALTER PUBLICATION supabase_realtime ADD TABLE public.orders,public.products,public.merchants,public.order_items,public.riders,public.support_tickets;